// Checks every rooftop mission mark against the ACTUAL GLB geometry.
//
// Why this exists, and why the collider checkers could not do it.
//
// New York's colliders are generated by rasterising the buildings into a height
// field, merging same-band cells into rectangles, and filling each rectangle to
// the TALLEST thing inside it. That is right for physics — nothing can be flown
// through — and it means a roof with a parapet is SOLID up to the parapet. The
// drone therefore rests a metre or two above the slab the pilot can see.
//
// A mission mark is drawn at its `groundY`, which has to be the height the
// aircraft rests at, or the release band is somewhere the drone cannot go. On a
// roof like that, the mark is then drawn a metre above the visible roof: a
// target hanging in mid-air over the building. That shipped, and every check in
// `check-multi-delivery-route.mjs` passed it — because all of them read the
// generated colliders, which by construction agree with themselves.
//
// The only thing that can settle it is the model. This script reads the GLB,
// rasterises the real triangles, and reports for each rooftop mark:
//
//   * the visible roof under it, and whether that is the `padBase` declared
//   * the collider deck, and whether that is the `groundY` declared
//   * whether the whole platform footprint stands on real roof at one height
//
// Usage:
//   node scripts/check-roof-marks.mjs            # report, exit 1 if wrong
//   node scripts/check-roof-marks.mjs --sites    # every place a pad could go
//
// Reads:  src/assets/models/new_york_city.opt.glb
//         src/renderer/scene/environment/NewYorkColliders.tsx
//         src/renderer/missions/multiPointDelivery.ts
//
// It is SLOW — a 23 MB Draco model has to be decoded — so it is its own command
// rather than part of the route check that runs on every coordinate change.

import { NodeIO } from '@gltf-transform/core';
import { ALL_EXTENSIONS } from '@gltf-transform/extensions';
import draco3d from 'draco3dgltf';
import fs from 'node:fs';
import process from 'node:process';

const MODEL = 'src/assets/models/new_york_city.opt.glb';
const COLLIDERS = 'src/renderer/scene/environment/NewYorkColliders.tsx';
const MISSION = 'src/renderer/missions/multiPointDelivery.ts';

/** Must match CITY_OFFSET in NewYorkEnv.tsx and the collider generator. */
const CITY_OFFSET = [61.68, 0, -30.56];
/** Material names the collider generator counts as BUILDING, so this samples the
 *  same geometry the boxes were derived from. */
const ROAD_RE = /street|lane|decal|grass|_LR_Facades$/i;
const WALK_RE = /side_walks|curb|simple_concrete/i;
const PROP_RE = /bark|trash|WetFloor|Street_Assets/i;
const FOLIAGE_RE = /foliage|leaf|leaves/i;
const isBuilding = (n) =>
  !ROAD_RE.test(n) && !WALK_RE.test(n) && !PROP_RE.test(n) && !FOLIAGE_RE.test(n);

/** The Guru's ceiling — nothing above this is worth sampling. */
const CEILING = 30;
/** How far a declared height may be from the measured one, metres. Tight: the
 *  numbers this is checking are read straight off this model. */
const TOL = 0.15;
/** How much wider than its ring a mark's platform is drawn — must match
 *  `RooftopPad` in MissionMarkers. */
const PAD_MARGIN = 0.8;

// ---- The model --------------------------------------------------------------

const io = new NodeIO().registerExtensions(ALL_EXTENSIONS).registerDependencies({
  'draco3d.decoder': await draco3d.createDecoderModule(),
});
const doc = await io.read(MODEL);

const tris = [];
for (const node of doc.getRoot().listNodes()) {
  const mesh = node.getMesh();
  if (!mesh) continue;
  const t = node.getWorldTranslation();
  const s = node.getWorldScale();
  const toWorld = (v) => [
    v[0] * s[0] + t[0] + CITY_OFFSET[0],
    v[1] * s[1] + t[1] + CITY_OFFSET[1],
    v[2] * s[2] + t[2] + CITY_OFFSET[2],
  ];
  for (const prim of mesh.listPrimitives()) {
    const mat = prim.getMaterial();
    if (!isBuilding(mat ? mat.getName() : '')) continue;
    const pos = prim.getAttribute('POSITION');
    const idx = prim.getIndices();
    const n = idx ? idx.getCount() : pos.getCount();
    const a = [0, 0, 0];
    const b = [0, 0, 0];
    const c = [0, 0, 0];
    for (let i = 0; i + 2 < n; i += 3) {
      pos.getElement(idx ? idx.getScalar(i) : i, a);
      pos.getElement(idx ? idx.getScalar(i + 1) : i + 1, b);
      pos.getElement(idx ? idx.getScalar(i + 2) : i + 2, c);
      const A = toWorld(a);
      const B = toWorld(b);
      const C = toWorld(c);
      // Only what the aircraft could ever be near.
      if (Math.min(A[1], B[1], C[1]) > CEILING) continue;
      tris.push({
        A,
        B,
        C,
        xmin: Math.min(A[0], B[0], C[0]),
        xmax: Math.max(A[0], B[0], C[0]),
        zmin: Math.min(A[2], B[2], C[2]),
        zmax: Math.max(A[2], B[2], C[2]),
      });
    }
  }
}

/**
 * The highest VISIBLE building surface at a point, or null where there is none.
 *
 * A point-in-triangle test on the XZ projection with the height interpolated
 * from the barycentric coordinates — which is what "the roof you can see from
 * above" means, and what a collider box's flat top is standing in for.
 */
function visible(x, z) {
  let best = null;
  for (const t of tris) {
    if (x < t.xmin || x > t.xmax || z < t.zmin || z > t.zmax) continue;
    const { A, B, C } = t;
    const d = (B[2] - C[2]) * (A[0] - C[0]) + (C[0] - B[0]) * (A[2] - C[2]);
    if (Math.abs(d) < 1e-9) continue;
    const l1 = ((B[2] - C[2]) * (x - C[0]) + (C[0] - B[0]) * (z - C[2])) / d;
    const l2 = ((C[2] - A[2]) * (x - C[0]) + (A[0] - C[0]) * (z - C[2])) / d;
    const l3 = 1 - l1 - l2;
    if (l1 < -1e-6 || l2 < -1e-6 || l3 < -1e-6) continue;
    const y = l1 * A[1] + l2 * B[1] + l3 * C[1];
    if (best === null || y > best) best = y;
  }
  return best;
}

// ---- The colliders ----------------------------------------------------------

const BOX =
  /\{ pos: \[(-?[\d.]+), (-?[\d.]+), (-?[\d.]+)\], args: \[(-?[\d.]+), (-?[\d.]+), (-?[\d.]+)\] \}/;
const boxes = [];
{
  let section = null;
  for (const line of fs.readFileSync(COLLIDERS, 'utf8').split('\n')) {
    const head = line.match(/^const ([A-Z_]+)\s*:/);
    if (head) {
      section = head[1];
      continue;
    }
    const m = BOX.exec(line);
    if (m && section !== 'SIDEWALK_PLATES') {
      boxes.push({ p: [+m[1], +m[2], +m[3]], h: [+m[4], +m[5], +m[6]] });
    }
  }
}

/** The height the AIRCRAFT rests at over a point: the top of the collider. */
function solid(x, z) {
  let top = 0;
  for (const b of boxes) {
    if (Math.abs(x - b.p[0]) <= b.h[0] && Math.abs(z - b.p[2]) <= b.h[2]) {
      top = Math.max(top, b.p[1] + b.h[1]);
    }
  }
  return top;
}

// ---- The marks --------------------------------------------------------------

function loadMarks() {
  const src = fs.readFileSync(MISSION, 'utf8');
  const list = /const DELIVERIES[^=]*= \[([\s\S]*?)\n\];/.exec(src);
  if (!list) throw new Error('could not read DELIVERIES from the mission file');
  return list[1]
    .split(/\n {2}\{\n/)
    .slice(1)
    .map((entry) => {
      const m = /bay\('([^']+)', (-?[\d.]+), (-?[\d.]+), \{([^}]*)\}\)/.exec(entry);
      if (!m) throw new Error(`could not read a destination from:\n${entry}`);
      const opt = (name) => {
        const hit = new RegExp(`\\b${name}: (-?[\\d.]+)`).exec(m[4]);
        return hit ? +hit[1] : undefined;
      };
      return {
        label: m[1],
        x: +m[2],
        z: +m[3],
        deck: opt('deck'),
        radius: opt('radius'),
        standsOn: opt('standsOn'),
      };
    });
}

let failures = 0;
function note(ok, name, detail) {
  if (!ok) failures++;
  console.log(`${ok ? '  ok ' : 'WRONG'}  ${name.padEnd(12)} ${detail}`);
}

if (process.argv.includes('--sites')) {
  // Every place a delivery platform could stand: the visible roof flat under
  // the whole footprint, the collider deck uniform above it, and a gap between
  // the two to build into. This is the sweep the mission's one rooftop came out
  // of; re-run it if the colliders are regenerated.
  const r = 2.6;
  console.log(`\nPlaces a ${r} m delivery platform can stand in New York City\n`);
  const found = [];
  for (let x = -118; x <= 118; x += 0.5) {
    for (let z = -95; z <= 95; z += 0.5) {
      const vis = visible(x, z);
      if (vis === null || vis < 3 || vis > CEILING - 4) continue;
      const col = solid(x, z);
      if (col < vis + 0.25 || col > CEILING - 2) continue;
      let ok = true;
      for (let a = 0; a < 16 && ok; a++) {
        for (const rr of [r * 0.6, r]) {
          const th = (a * Math.PI) / 8;
          const v = visible(x + Math.cos(th) * rr, z + Math.sin(th) * rr);
          const c = solid(x + Math.cos(th) * rr, z + Math.sin(th) * rr);
          if (v === null || Math.abs(v - vis) > 0.2 || Math.abs(c - col) > 0.2) ok = false;
        }
      }
      if (ok) found.push({ x, z, roof: +vis.toFixed(2), deck: +col.toFixed(2) });
    }
  }
  const seen = [];
  for (const f of found) {
    if (seen.some((p) => Math.hypot(p.x - f.x, p.z - f.z) < 8)) continue;
    seen.push(f);
    console.log(
      `  [${f.x}, ${f.z}]   roof ${f.roof} m   deck ${f.deck} m   platform ${(f.deck - f.roof).toFixed(2)} m tall`,
    );
  }
  console.log(`\n${seen.length} site(s), ${found.length} usable samples.\n`);
  process.exit(0);
}

console.log(`\nRooftop marks against the model — ${tris.length} building triangles under ${CEILING} m\n`);

for (const d of loadMarks()) {
  if (d.standsOn === undefined) {
    // Not a rooftop mark. It still has to be standing on what it says: a mark on
    // the street whose deck is above the visible ground would float too.
    const vis = visible(d.x, d.z);
    note(
      vis === null || vis <= d.deck + TOL,
      d.label,
      vis === null
        ? 'street-level mark, no building geometry over it'
        : `street-level mark with building geometry at ${vis.toFixed(2)} m`,
    );
    continue;
  }

  const roof = visible(d.x, d.z);
  const deck = solid(d.x, d.z);
  note(
    roof !== null && Math.abs(roof - d.standsOn) <= TOL,
    d.label,
    `declares it stands on ${d.standsOn} m, the model's roof is ${roof === null ? 'nothing' : roof.toFixed(2) + ' m'}`,
  );
  note(
    Math.abs(deck - d.deck) <= TOL,
    d.label,
    `declares a deck of ${d.deck} m, the aircraft rests at ${deck.toFixed(2)} m`,
  );

  // The platform's whole footprint, not just its middle. A pad half over the
  // edge is the same bug one storey further along.
  const r = d.radius + PAD_MARGIN;
  let worstRoof = 0;
  let worstDeck = 0;
  for (let i = 0; i < 24; i++) {
    const a = (i / 24) * Math.PI * 2;
    for (const rr of [r * 0.6, r]) {
      const v = visible(d.x + Math.cos(a) * rr, d.z + Math.sin(a) * rr);
      const c = solid(d.x + Math.cos(a) * rr, d.z + Math.sin(a) * rr);
      worstRoof = Math.max(worstRoof, v === null ? 99 : Math.abs(v - d.standsOn));
      worstDeck = Math.max(worstDeck, Math.abs(c - d.deck));
    }
  }
  note(
    worstRoof <= 0.2,
    d.label,
    `platform footprint of ${r.toFixed(1)} m sits on roof that varies by ${worstRoof > 90 ? 'open air' : worstRoof.toFixed(2) + ' m'}`,
  );
  note(worstDeck <= 0.2, d.label, `the deck under it varies by ${worstDeck.toFixed(2)} m`);
}

console.log(
  failures === 0
    ? '\nEvery mark stands on what it says it stands on.\n'
    : `\n${failures} mark(s) disagree with the model. A mark drawn above the roof it names is the one the pilot sees floating.\n`,
);
process.exit(failures === 0 ? 0 : 1);
